node -e "
const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// Get order
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-9497C0'\").get();
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Get order items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-9497C0'\").all();
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Get fulfillments
const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'ORD-9497C0'\").all();
console.log('\n=== FULFILLMENTS ===');
console.log(JSON.stringify(fulfillments, null, 2));

// Get payments
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-9497C0'\").all();
console.log('\n=== PAYMENTS ===');
console.log(JSON.stringify(payments, null, 2));
"

