const p2 = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-190CB7'\").get();

// Check for variants
const v1 = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-39F904'\").all();
const v2 = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-190CB7'\").all();

// Check warranties
const w1 = db.prepare(\"SELECT * FROM warranties WHERE product_id = 'PROD-39F904' OR order_id = 'ORD-9497C0'\").all();

console.log('=== PRODUCT 1: Levi T-Shirt ===');
console.log(JSON.stringify(p1, null, 2));
console.log('\n=== PRODUCT 1 VARIANTS ===');
console.log(JSON.stringify(v1, null, 2));
console.log('\n=== PRODUCT 2: OXO Salad Spinner ===');
console.log(JSON.stringify(p2, null, 2));
console.log('\n=== PRODUCT 2 VARIANTS ===');
console.log(JSON.stringify(v2, null, 2));
console.log('\n=== WARRANTIES ===');
console.log(JSON.stringify(w1, null, 2));
"

